import { test, expect } from 'bun:test'
import { LinkedList } from './linkedlist'

test('insert 和 toArray', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.insert(2)
  list.insert(3)
  expect(list.toArray()).toEqual([1, 2, 3])
  expect(list.size).toBe(3)
})

test('at 索引访问', () => {
  const list = new LinkedList<string>()
  list.insert('a')
  list.insert('b')
  list.insert('c')
  expect(list.at(0)).toBe('a')
  expect(list.at(1)).toBe('b')
  expect(list.at(2)).toBe('c')
  expect(list.at(3)).toBeUndefined()
  expect(list.at(-1)).toBeUndefined()
})

test('remove 中间元素', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.insert(2)
  list.insert(3)
  expect(list.remove(2)).toBe(true)
  expect(list.toArray()).toEqual([1, 3])
  expect(list.size).toBe(2)
})

test('remove 头部元素', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.insert(2)
  expect(list.remove(1)).toBe(true)
  expect(list.toArray()).toEqual([2])
})

test('remove 尾部元素', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.insert(2)
  expect(list.remove(2)).toBe(true)
  expect(list.toArray()).toEqual([1])
})

test('remove 不存在的元素', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  expect(list.remove(99)).toBe(false)
  expect(list.size).toBe(1)
})

test('remove 到空链表', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.remove(1)
  expect(list.toArray()).toEqual([])
  expect(list.size).toBe(0)
})

test('空链表操作', () => {
  const list = new LinkedList<number>()
  expect(list.toArray()).toEqual([])
  expect(list.at(0)).toBeUndefined()
  expect(list.size).toBe(0)
})

test('泛型支持字符串', () => {
  const list = new LinkedList<string>()
  list.insert('hello')
  list.insert('world')
  expect(list.toArray()).toEqual(['hello', 'world'])
})

// 验证删除后链表结构正确（连续删除+插入）
test('混合操作', () => {
  const list = new LinkedList<number>()
  list.insert(1)
  list.insert(2)
  list.insert(3)
  list.insert(4)
  list.remove(2) // [1,3,4]
  list.remove(4) // [1,3]
  list.insert(5) // [1,3,5]
  expect(list.toArray()).toEqual([1, 3, 5])
})
